class Solution {
public:
    vector<vector<int>> largeGroupPositions(string s) {
        vector<vector<int>> result;
        for (int i = 0, j; i < (int)s.size(); i = j) {
            j = i + 1;
            while (j < (int)s.size() && s[j] == s[i]) ++j;
            if (j - i >= 3) result.push_back({i, j - 1});
        }
        return result;
    }
};
